import json
with open('/Users/michael/Code/cipher-box/designs/cipher-box-design.pen', 'r') as f:
    data = json.load(f)

children = data.get('children', [])

# Find the share dialog and examine its structure
def find_frame(items, target_id, depth=0):
    for item in items:
        if isinstance(item, dict):
            if item.get('id') == target_id:
                return item
            if 'children' in item:
                result = find_frame(item['children'], target_id, depth+1)
                if result:
                    return result
    return None

# Get P14 - Share Dialog Modal structure
dialog = find_frame(children, 'oYyAB')
if dialog:
    def print_tree(node, depth=0):
        indent = '  ' * depth
        name = node.get('name', '?')
        ntype = node.get('type', '?')
        nid = node.get('id', '?')
        w = node.get('width', '')
        h = node.get('height', '')
        fill = node.get('fill', '')
        content = ''
        if ntype == 'text':
            content = f' \"{node.get(\"content\", \"\")}\"'
        print(f'{indent}{ntype}: {name} [{nid}] {w}x{h} fill={fill}{content}')
        for child in node.get('children', []):
            if isinstance(child, dict):
                print_tree(child, depth+1)
    print_tree(dialog)
